1	/**
2	 * ShiftInviteService — convite push de turno (Slice 1, R5/R7/R8).
3	 *
4	 * Fluxo push: EMPRESA cria application com status='invited' para worker da equipe.
5	 * Fluxo de resposta: WORKER aceita ('accepted') ou recusa ('declined').
6	 *
7	 * Avisos do architect (ADR-001):
8	 * 1. A transição de status do convite (invited → accepted/declined) NÃO é forçada por RLS;
9	 *    validamos a máquina de estados AQUI no service.
10	 * 2. Recusa é NEUTRA (zero punição — R7): só muda status para 'declined'.
11	 * 3. Criar-turno e aceite NÃO chamam reserve_escrow (postpago é Slice 2).
12	 *    accepted aqui = status 'hired' (confirmado no turno) SEM escrow. Slice 2 preenche o gap.
13	 * 4. inserts de review devem passar direction explicitamente — ver ReviewService em types/index.ts.
14	 */
15	
16	import { supabase } from '../lib/supabase';
17	import { invokeFunction } from './api';
18	import { logError } from '../lib/logger';
19	import { TeamConnectionService } from './teamConnectionService';
20	import type {
21	  Application,
22	  ApplicationStatus,
23	  InvitationResponse,
24	} from '../types';
25	
26	// ---------------------------------------------------------------------------
27	// Tipos do resultado estruturado de autorização de pagamento
28	// ---------------------------------------------------------------------------
29	
30	export type AuthorizePaymentOutcome =
31	  | { kind: 'ok'; asaasPaymentId: string }
32	  | { kind: 'fallback_charge_on_demand'; reason: string }
33	  | { kind: 'card_declined'; errorMsg: string };
34	
35	// ---------------------------------------------------------------------------
36	// Helper interno: disparar pré-autorização postpago (best-effort, não bloqueia o aceite)
37	// ---------------------------------------------------------------------------
38	
39	/**
40	 * Invoca asaas-authorize-payment após o aceite do convite.
41	 * Retorna um resultado estruturado:
42	 *  - 'ok'                    : hold criado com sucesso.
43	 *  - 'fallback_charge_on_demand': pré-auth não habilitada; cobrança será na conclusão.
44	 *  - 'card_declined'         : cartão recusado — empresa deve verificar o método de pagamento.
45	 *
46	 * Falha NÃO reverte o status 'hired' — o aceite já aconteceu no DB.
47	 * Em 'card_declined', uma notificação in-app é criada para a empresa.
48	 */
49	async function dispatchAuthorizePayment(
50	  jobId: string,
51	  applicationId: string,
52	  companyOwnerId: string,
53	): Promise<AuthorizePaymentOutcome> {
54	  try {
55	    // invokeFunction lança se HTTP status >= 400 (comportamento padrão de api.ts)
56	    const result = await invokeFunction('asaas-authorize-payment', { jobId, applicationId }) as {
57	      success?: boolean;
58	      status?: string;
59	      fallback?: boolean;
60	      reason?: string;
61	      asaasPaymentId?: string;
62	    };
63	
64	    if (result?.status === 'charge_on_demand') {
65	      return { kind: 'fallback_charge_on_demand', reason: result.reason ?? '' };
66	    }
67	
68	    return { kind: 'ok', asaasPaymentId: result?.asaasPaymentId ?? '' };
69	  } catch (authErr) {
70	    const errMsg = authErr instanceof Error ? authErr.message : 'Erro desconhecido na autorização.';
71	
72	    // Detectar recusa de cartão: a Edge Function agora lança erros específicos (não engole mais
73	    // recusas). Qualquer erro que não seja "pré-auth não disponível" é tratado como card_declined
74	    // para fins de notificação — o flow de captura fallback ainda ocorre na conclusão.
75	    logError('shiftInvite.authorizePayment (best-effort)', authErr);
76	
77	    // Notificar empresa sobre falha no cartão (best-effort — não bloqueia o aceite)
78	    if (companyOwnerId) {
79	      try {
80	        await supabase.from('notifications').insert({
81	          user_id: companyOwnerId,
82	          type: 'payment',
83	          title: 'Falha na autorização do cartão',
84	          message:
85	            `A autorização do pagamento para o turno falhou: ${errMsg}. ` +
86	            'Verifique o método de pagamento cadastrado para garantir que o freela receba.',
87	          link: '/company/wallet',
88	        });
89	      } catch (notifErr) {
90	        logError('shiftInvite.authorizePayment.notif', notifErr);
91	      }
92	    }
93	
94	    return { kind: 'card_declined', errorMsg: errMsg };
95	  }
96	}
97	
98	// ---------------------------------------------------------------------------
99	// Tipos de parâmetros e resultado
100	// ---------------------------------------------------------------------------
101	
102	/** Janela de expiração do convite em horas (R8). Default = 48h. */
103	const DEFAULT_INVITE_EXPIRY_HOURS = 48;
104	
105	export interface InviteWorkerToShiftOptions {
106	  /** Horas até o convite expirar (default: 48). */
107	  expiresInHours?: number;
108	  /** Mensagem personalizada para a notificação (opcional). */
109	  message?: string;
110	}
111	
112	export interface InviteWorkerResult {
113	  application: Application | null;
114	  error?: string;
115	  /** true quando já existe um convite pendente (idempotência). */
116	  alreadyInvited?: boolean;
117	}
118	
119	export interface RespondToInviteResult {
120	  success: boolean;
121	  error?: string;
122	}
123	
124	// ---------------------------------------------------------------------------
125	// Helpers internos
126	// ---------------------------------------------------------------------------
127	
128	/** Obtém o company_id da sessão autenticada (empresa). */
129	async function getAuthCompanyId(): Promise<string> {
130	  const {
131	    data: { user },
132	  } = await supabase.auth.getUser();
133	  if (!user) throw new Error('Sessão expirada. Faça login novamente.');
134	
135	  const { data: company, error } = await supabase
136	    .from('companies')
137	    .select('id')
138	    .eq('owner_id', user.id)
139	    .maybeSingle();
140	
141	  if (error) throw error;
142	  if (!company) throw new Error('Perfil de empresa não encontrado.');
143	
144	  return company.id as string;
145	}
146	
147	/** Calcula timestamp de expiração. */
148	function calcExpiry(hours: number): string {
149	  const d = new Date();
150	  d.setHours(d.getHours() + hours);
151	  return d.toISOString();
152	}
153	
154	// ---------------------------------------------------------------------------
155	// ShiftInviteService
156	// ---------------------------------------------------------------------------
157	
158	export const ShiftInviteService = {
159	  // -------------------------------------------------------------------------
160	  // EMPRESA: convidar worker para turno
161	  // -------------------------------------------------------------------------
162	
163	  /**
164	   * Convida um worker da equipe para um turno específico.
165	   *
166	   * Pré-condições verificadas:
167	   *  1. O worker é conexão 'accepted' da empresa (R2 — lista fechada).
168	   *  2. Não existe convite ativo (invited) para o mesmo job+worker.
169	   *
170	   * Ações:
171	   *  1. Insere em `applications` com status='invited'.
172	   *  2. Cria notificação in-app (insert em `notifications`).
173	   *  3. Invoca `send-notification` para entrega por e-mail.
174	   *
175	   * Não chama reserve_escrow (Slice 2).
176	   *
177	   * @param jobId    UUID do turno (job).
178	   * @param workerId UUID do worker a convidar.
179	   * @param opts     Opções adicionais.
180	   */
181	  async inviteWorkerToShift(
182	    jobId: string,
183	    workerId: string,
184	    opts: InviteWorkerToShiftOptions = {},
185	  ): Promise<InviteWorkerResult> {
186	    try {
187	      const companyId = await getAuthCompanyId();
188	
189	      // 1. Validar que o worker está na equipe aceita (R2)
190	      const inTeam = await TeamConnectionService.isWorkerInTeam(companyId, workerId);
191	      if (!inTeam) {
192	        return {
193	          application: null,
194	          error:
195	            'O freela não está na sua equipe. Adicione-o primeiro para poder convidar.',
196	        };
197	      }
198	
199	      // 2. Verificar se já existe convite pendente (idempotência)
200	      const { data: existing, error: checkErr } = await supabase
201	        .from('applications')
202	        .select('id, status')
203	        .eq('job_id', jobId)
204	        .eq('worker_id', workerId)
205	        .maybeSingle();
206	
207	      if (checkErr) {
208	        logError('shiftInvite.inviteWorkerToShift.check', checkErr);
209	        return { application: null, error: 'Erro ao verificar convite existente.' };
210	      }
211	
212	      if (existing) {
213	        // Já existe application (qualquer status)
214	        if (existing.status === 'invited') {
215	          return {
216	            application: existing as Application,
217	            alreadyInvited: true,
218	          };
219	        }
220	        return {
221	          application: null,
222	          error: `Já existe uma candidatura para este turno com status '${existing.status}'.`,
223	        };
224	      }
225	
226	      // 3. Calcular expiração
227	      const expiresInHours = opts.expiresInHours ?? DEFAULT_INVITE_EXPIRY_HOURS;
228	      const expiresAt = calcExpiry(expiresInHours);
229	      const now = new Date().toISOString();
230	
231	      // 4. Inserir convite em applications
232	      const { data: application, error: insertErr } = await supabase
233	        .from('applications')
234	        .insert({
235	          job_id: jobId,
236	          worker_id: workerId,
237	          status: 'invited' as ApplicationStatus,
238	          invited_by_company_at: now,
239	          invitation_expires_at: expiresAt,
240	        })
241	        .select()
242	        .single();
243	
244	      if (insertErr) {
245	        if (insertErr.code === '23505') {
246	          return { application: null, alreadyInvited: true };
247	        }
248	        logError('shiftInvite.inviteWorkerToShift.insert', insertErr);
249	        return { application: null, error: 'Não foi possível criar o convite.' };
250	      }
251	
252	      // 5. Notificação in-app (insert direto em notifications)
253	      const { error: notifErr } = await supabase.from('notifications').insert({
254	        user_id: workerId,
255	        type: 'status_change',
256	        title: 'Novo convite de turno',
257	        message:
258	          opts.message ??
259	          'Você recebeu um convite para um turno. Acesse "Convites" para aceitar ou recusar.',
260	        link: `/my-jobs`,
261	      });
262	
263	      if (notifErr) {
264	        // Não bloqueia — a application foi criada; notificação é best-effort
265	        logError('shiftInvite.inviteWorkerToShift.notif', notifErr);
266	      }
267	
268	      // 6. Entrega por e-mail via send-notification (best-effort)
269	      try {
270	        await invokeFunction('send-notification', {
271	          userId: workerId,
272	          type: 'shift_invite',
273	          data: {
274	            jobId,
275	            applicationId: application.id,
276	            expiresAt,
277	          },
278	        });
279	      } catch (emailErr) {
280	        // Edge function falhou — não bloqueia o convite
281	        logError('shiftInvite.inviteWorkerToShift.email', emailErr);
282	      }
283	
284	      return { application: application as Application };
285	    } catch (err) {
286	      logError('shiftInvite.inviteWorkerToShift', err);
287	      return {
288	        application: null,
289	        error: err instanceof Error ? err.message : 'Erro inesperado.',
290	      };
291	    }
292	  },
293	
294	  // -------------------------------------------------------------------------
295	  // WORKER: responder ao convite (aceitar ou recusar)
296	  // -------------------------------------------------------------------------
297	
298	  /**
299	   * Worker responde a um convite de turno.
300	   *
301	   * Máquina de estados (validada aqui — ADR-001):
302	   *   'invited' → 'hired'    (quando accepted)
303	   *   'invited' → 'declined' (quando declined — NEUTRO, zero punição — R7)
304	   *
305	   * NÃO chama reserve_escrow (postpago é Slice 2; Slice 2 adiciona o hook aqui).
306	   *
307	   * @param applicationId UUID da application (convite).
308	   * @param response      'accepted' | 'declined'.
309	   */
310	  async respondToInvite(
311	    applicationId: string,
312	    response: InvitationResponse,
313	  ): Promise<RespondToInviteResult> {
314	    try {
315	      const {
316	        data: { user },
317	      } = await supabase.auth.getUser();
318	      if (!user) return { success: false, error: 'Sessão expirada.' };
319	
320	      // 1. Buscar application atual (validar máquina de estados)
321	      const { data: current, error: fetchErr } = await supabase
322	        .from('applications')
323	        .select('id, status, worker_id, job_id, invited_by_company_at, invitation_expires_at')
324	        .eq('id', applicationId)
325	        .maybeSingle();
326	
327	      if (fetchErr) {
328	        logError('shiftInvite.respondToInvite.fetch', fetchErr);
329	        return { success: false, error: 'Convite não encontrado.' };
330	      }
331	      if (!current) return { success: false, error: 'Convite não encontrado.' };
332	      if (current.worker_id !== user.id) {
333	        return { success: false, error: 'Este convite não é para você.' };
334	      }
335	      if (current.status !== 'invited') {
336	        return {
337	          success: false,
338	          error: `Transição inválida: status atual é '${current.status}', esperado 'invited'.`,
339	        };
340	      }
341	
342	      // 2. Verificar expiração (R8)
343	      if (current.invitation_expires_at) {
344	        const expiresAt = new Date(current.invitation_expires_at as string);
345	        if (expiresAt < new Date()) {
346	          return {
347	            success: false,
348	            error: 'Este convite expirou. O operador precisará reenviar um novo convite.',
349	          };
350	        }
351	      }
352	
353	      // 3. Mapear response → status final
354	      //    accepted → 'hired' (turno confirmado para os dois lados — sem escrow neste slice)
355	      //    declined → 'declined' (neutro — R7)
356	      const newStatus: ApplicationStatus = response === 'accepted' ? 'hired' : 'declined';
357	      const now = new Date().toISOString();
358	
359	      const { error: updateErr } = await supabase
360	        .from('applications')
361	        .update({
362	          status: newStatus,
363	          invitation_response: response,
364	          invitation_responded_at: now,
365	        })
366	        .eq('id', applicationId)
367	        .eq('worker_id', user.id);
368	
369	      if (updateErr) {
370	        logError('shiftInvite.respondToInvite.update', updateErr);
371	        return { success: false, error: 'Erro ao registrar resposta.' };
372	      }
373	
374	      // 4. Resolver o owner da empresa (necessário tanto para notificação de aceite quanto
375	      //    para notificação de falha de cartão em dispatchAuthorizePayment).
376	      let companyOwnerId: string | null = null;
377	      if (response === 'accepted') {
378	        const { data: jobRow } = await supabase
379	          .from('applications')
380	          .select('job:jobs(company_id)')
381	          .eq('id', applicationId)
382	          .maybeSingle();
383	
384	        const companyId = (jobRow?.job as { company_id?: string } | null)?.company_id;
385	        if (companyId) {
386	          const { data: companyRow } = await supabase
387	            .from('companies')
388	            .select('owner_id')
389	            .eq('id', companyId)
390	            .maybeSingle();
391	          companyOwnerId = companyRow?.owner_id ?? null;
392	        }
393	      }
394	
395	      // 5. Pré-autorização postpago (best-effort — não bloqueia o aceite em caso de falha).
396	      //    Modo 'authorize': cria hold no cartão da empresa. Modo 'charge_on_demand': no-op aqui.
397	      //    A captura (ou cobrança direta) ocorre na conclusão via asaas-capture-payment.
398	      //    Em card_declined, dispatchAuthorizePayment já envia notificação à empresa.
399	      if (response === 'accepted') {
400	        await dispatchAuthorizePayment(current.job_id, applicationId, companyOwnerId ?? '');
401	      }
402	
403	      // 6. Notificação in-app para a empresa sobre o aceite (best-effort)
404	      if (response === 'accepted' && companyOwnerId) {
405	        const { error: notifErr } = await supabase.from('notifications').insert({
406	          user_id: companyOwnerId,
407	          type: 'status_change',
408	          title: 'Freela aceitou o turno',
409	          message: 'Um freela aceitou seu convite de turno.',
410	          link: `/company/jobs/${current.job_id}/candidates`,
411	        });
412	
413	        if (notifErr) {
414	          logError('shiftInvite.respondToInvite.notif', notifErr);
415	        }
416	      }
417	
418	      return { success: true };
419	    } catch (err) {
420	      logError('shiftInvite.respondToInvite', err);
421	      return {
422	        success: false,
423	        error: err instanceof Error ? err.message : 'Erro inesperado.',
424	      };
425	    }
426	  },
427	
428	  // -------------------------------------------------------------------------
429	  // Listagem de convites pendentes (worker)
430	  // -------------------------------------------------------------------------
431	
432	  /**
433	   * Lista convites de turno pendentes ('invited') do worker autenticado.
434	   * Inclui dados do job e da empresa para a aba "Convites".
435	   */
436	  async listPendingInvites(): Promise<Application[]> {
